package com.medtrack.tracking.dto; import com.medtrack.tracking.entity.TrackingEvent; import java.time.Instant; import java.util.*; public record TrackingResponse(UUID shipmentId,List<Event>events){public record Event(String status,String locationName,Double latitude,Double longitude,String remarks,Instant timestamp){}public static Event of(TrackingEvent e){return new Event(e.getMilestoneStatus().name(),e.getLocationName(),e.getLatitude(),e.getLongitude(),e.getRemarks(),e.getEventTimestamp());}}
